22	function MagneticButton({ children, className, onClick, style, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
23	  const elRef = useRef<HTMLButtonElement>(null);
24	  const textRef = useRef<HTMLSpanElement>(null);
25	  const handleMouseMove = (e: React.MouseEvent<HTMLButtonElement>) => {
26	    if (!elRef.current || !textRef.current) return;
27	    const { left, top, width, height } = elRef.current.getBoundingClientRect();
28	    textRef.current.style.transform = `translate(${(e.clientX - (left + width / 2)) * 0.4}px, ${(e.clientY - (top + height / 2)) * 0.4}px)`;
29	  };
30	  const handleMouseLeave = () => { if (textRef.current) textRef.current.style.transform = "translate(0px, 0px)"; };
31	  return (
32	    <button ref={elRef} className={className} onClick={onClick} onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave} style={style} {...props}>
33	      <span ref={textRef} style={{ display: "inline-flex", alignItems: "center", gap: "inherit", pointerEvents: "none", transition: "transform 0.4s cubic-bezier(0.23, 1, 0.32, 1)" }}>
34	        {children}
35	      </span>
36	    </button>
37	  );
38	}
