                className="absolute top-3 right-3 z-10 w-8 h-8 rounded-full bg-[#000a36]/10 hover:bg-[#000a36]/20 flex items-center justify-center transition-colors"
              >
                <X className="w-4 h-4 text-[#000a36]" />
