87	    queryKey: ["/api/merchants", merchantId, "active-transaction"],
88	    queryFn: async () => {
89	      const r = await fetch(`/api/merchants/${merchantId}/active-transaction`);
90	      if (!r.ok) throw new Error("Failed to fetch active transaction");
91	      return r.json();
92	    },
93	    // SSE keeps this cache live via queryClient.setQueryData — no polling needed.
94	    // A 30 s fallback refetch guards against SSE gaps (disconnect, reconnect lag).
95	    refetchInterval: 30000,
96	    enabled: !!merchantId,
97	  });
98	
99	  const { data: taptStones = [] } = useQuery({
100	    queryKey: ["/api/merchants", merchantId, "tapt-stones"],
101	    queryFn: async () => {
102	      const authToken = localStorage.getItem("authToken");
103	      const r = await fetch(`/api/merchants/${merchantId}/tapt-stones`, {
104	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
105	      });
106	      if (!r.ok) throw new Error("Failed to fetch tapt stones");
107	      return r.json();
108	    },
109	    enabled: !!merchantId,
110	  });
111	
112	  const { data: allTransactions = [] } = useQuery({
113	    queryKey: ["/api/merchants", merchantId, "transactions"],
114	    queryFn: async () => {
115	      const authToken = localStorage.getItem("authToken");
116	      const r = await fetch(`/api/merchants/${merchantId}/transactions`, {
117	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
118	      });
119	      if (!r.ok) throw new Error("Failed to fetch transactions");
120	      return r.json();
121	    },
122	    refetchInterval: 5000,
123	    enabled: !!merchantId,
124	  });
125	
126	  useEffect(() => {
127	    if ((taptStones as any[]).length > 0 && selectedStoneId === null) {
128	      setSelectedStoneId((taptStones as any[])[0].id);
129	    }
130	  }, [taptStones, selectedStoneId]);
131	
132	  useEffect(() => {
133	    if (!merchantId) return;
134	    sseClient.connect(merchantId);
135	    sseClient.subscribe("transaction_updated", (message) => {
136	      const tx = message.transaction ?? null;
137	      queryClient.setQueryData(["/api/merchants", merchantId, "active-transaction"], tx);
138	      // Keep allTransactions cache in sync for all updates so split progress,
139	      // status changes, and completedSplits increments appear immediately.
140	      if (tx) {
141	        queryClient.setQueryData<any[]>(
142	          ["/api/merchants", merchantId, "transactions"],
143	          (prev: any[] = []) => {
144	            const exists = prev.some((t: any) => t.id === tx.id);
145	            return exists
146	              ? prev.map((t: any) => (t.id === tx.id ? tx : t))
147	              : [tx, ...prev];
148	          }
149	        );
150	      }
151	    });
152	    return () => { sseClient.disconnect(); };
153	  }, [merchantId, queryClient]);
154	
155	  useDeviceStatusMonitoring();
156	  useSSEConnectionMonitoring(merchantId ?? 0);
157	
158	  useEffect(() => {
159	    const prev = prevTransactionStatusRef.current;
160	    const status = activeTransaction?.status ?? null;
161	    if (status === "completed" && prev && prev !== "completed") {
162	      playSuccessChime();
163	      const amount = activeTransaction?.price
164	        ? parseFloat(activeTransaction.price).toFixed(2)
165	        : undefined;
166	      setSuccessNotif({ id: `success-${Date.now()}`, message: "Payment Received", amount });
167	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
168	    }
169	    prevTransactionStatusRef.current = status;
170	  }, [activeTransaction?.status]);
171	
172	  const createTransactionMutation = useMutation({
173	    mutationFn: async (data: { itemName: string; price: string; selectedStoneId?: number; splitEnabled?: boolean }) => {
174	      const r = await apiRequest("POST", "/api/transactions", {
175	        merchantId,
176	        itemName: data.itemName,
177	        price: data.price,
178	        status: "pending",
179	        selectedStoneId: data.selectedStoneId,
180	        splitEnabled: data.splitEnabled ?? false,
181	      });
182	      return r.json();
183	    },
184	    onSuccess: () => {
185	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
186	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
187	    },
188	    onError: () => {
189	      toast({ title: "Error", description: "Failed to create transaction", variant: "destructive" });
190	    },
191	  });
192	
193	  const createStoneMutation = useMutation({
194	    mutationFn: async () => {
195	      const stoneNumber = ((taptStones as any[])?.length || 0) + 1;
196	      const r = await apiRequest("POST", `/api/merchants/${merchantId}/tapt-stones`, {
197	        name: `Stone ${stoneNumber}`,
198	        stoneNumber,
199	      });
200	      return r.json();
201	    },
202	    onSuccess: () => {
203	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "tapt-stones"] });
204	    },
205	  });
206	
207	  const renameStoneMutation = useMutation({
208	    mutationFn: async ({ stoneId, name }: { stoneId: number; name: string }) => {
209	      const r = await apiRequest("PUT", `/api/merchants/${merchantId}/tapt-stones/${stoneId}`, { name });
210	      return r.json();
211	    },
212	    onSuccess: () => {
213	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "tapt-stones"] });
214	    },
215	  });
216	
217	  const deleteStoneMutation = useMutation({
218	    mutationFn: async (stoneId: number) => {
219	      const r = await apiRequest("DELETE", `/api/merchants/${merchantId}/tapt-stones/${stoneId}`);
220	      return r.ok ? {} : r.json();
221	    },
222	    onSuccess: (_data, stoneId) => {
223	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "tapt-stones"] });
224	      if (selectedStoneId === stoneId) setSelectedStoneId(null);
225	    },
226	  });
227	
228	  const cancelTransactionMutation = useMutation({
229	    mutationFn: async (transactionId: number) => {
230	      const r = await apiRequest("POST", `/api/transactions/${transactionId}/cancel`, {});
231	      return r.json();
232	    },
233	    onSuccess: () => {
234	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
235	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
236	    },
237	    onError: () => {
238	      toast({ title: "Error", description: "Failed to cancel transaction", variant: "destructive" });
239	    },
240	  });
241	
242	  const startTapToPayPayment = async (txOverride?: any) => {
243	    const tx = txOverride ?? activeTransaction;
244	    if (!tx) {
245	      toast({ title: "No Transaction", description: "Create a transaction first.", variant: "destructive" });
246	      return;
247	    }
248	    setTapToPayStatus("waiting");
249	    setTapToPayApproved(null);
250	    setShowTapToPayOverlay(true);
251	    try {
252	      let bridgeResult: { approved: boolean; token?: string; cancelled?: boolean; error?: string };
253	      if (canTapToPay()) {
254	        bridgeResult = await (window as any).TaptPay!.startTapToPay({
255	          amount: parseFloat(tx.price),
256	          currency: "NZD",
257	          merchantName: merchant?.businessName || "TaptPay",
258	        });
259	      } else if (import.meta.env.DEV) {
260	        await new Promise(r => setTimeout(r, 2000));
261	        bridgeResult = { approved: true, token: `SIM_TOKEN_${Date.now()}` };
262	      } else {
263	        setTapToPayStatus("idle");
264	        setShowTapToPayOverlay(false);
265	        toast({ title: "Not available", description: "Tap to Pay requires the TaptPay iOS app.", variant: "destructive" });
266	        return;
267	      }
268	      if (bridgeResult.cancelled) {
269	        setTapToPayStatus("idle");
270	        setShowTapToPayOverlay(false);
271	        toast({ title: "Cancelled", description: "Tap to Pay was cancelled." });
272	        return;
273	      }
274	      setTapToPayStatus("processing");
275	      const authToken = localStorage.getItem("authToken");
276	      const r = await fetch("/api/transactions/tap-to-pay", {
277	        method: "POST",
278	        headers: { "Content-Type": "application/json", Authorization: `Bearer ${authToken}` },
279	        body: JSON.stringify({
280	          merchantId,
281	          transactionId: tx.id,
282	          amount: parseFloat(tx.price),
283	          windcaveToken: bridgeResult.token,
284	        }),
285	      });
286	      if (!r.ok) {
287	        const errData = await r.json().catch(() => ({}));
288	        throw new Error(errData.message || `Processor error (${r.status})`);
289	      }
290	      const data = await r.json();
291	      setTapToPayApproved(data.approved);
292	      setTapToPayStatus(data.approved ? "completed" : "failed");
293	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
294	      setTimeout(() => { setShowTapToPayOverlay(false); setTapToPayStatus("idle"); setTapToPayApproved(null); }, 3500);
295	    } catch (err: any) {
296	      setTapToPayStatus("failed");
297	      setTapToPayApproved(false);
298	      toast({ title: "Payment error", description: err?.message || "Tap to Pay failed", variant: "destructive" });
299	    }
300	  };
301	
302	  const closeTapToPayOverlay = () => {
303	    setShowTapToPayOverlay(false);
304	    setTapToPayStatus("idle");
305	    setTapToPayApproved(null);
306	  };
307	
308	  if (!merchantId) {
309	    window.location.href = "/login";
310	    return <div>Redirecting...</div>;
311	  }
312	
313	  // Terminal always resets to $0.00 after send — sent transactions live in the stack, not the pending display
314	  const sent = (allTransactions as any[])
315	    .filter((tx: any) => ["pending", "processing", "completed", "failed"].includes(tx.status))
316	    .slice(0, 10)
317	    .map((tx: any) => {
318	      let displayStatus: string;
319	      if (tx.status === "completed") displayStatus = "paid";
320	      else if (tx.status === "failed") displayStatus = "declined";
321	      else if (tx.status === "processing") displayStatus = "processing";
322	      else displayStatus = "awaiting payment";
323	      return {
324	        id: tx.id,
325	        name: tx.itemName,
326	        amount: Math.round(parseFloat(tx.price) * 100),
327	        status: displayStatus,
328	        splitEnabled: !!tx.splitEnabled,
329	        isSplit: !!tx.isSplit,
330	        completedSplits: tx.completedSplits != null ? Number(tx.completedSplits) : 0,
331	        totalSplits: tx.totalSplits != null ? Number(tx.totalSplits) : 1,
332	      };
333	    });
334	
335	  const liveState = { items: [], pending: null, sent };
336	
337	  const liveStones = (taptStones as any[]).map((s: any) => ({
338	    id: s.id,
339	    name: s.name || `Board #${s.stoneNumber}`,
340	    stoneNumber: s.stoneNumber,
341	  }));
342	
343	  const livePayLink = `${window.location.origin}/pay/${merchantId}${selectedStoneId ? `/stone/${selectedStoneId}` : ""}`;
344	
345	  const qrElement = (
346	    <QRCodeDisplay
347	      merchantId={merchantId}
348	      stoneId={selectedStoneId ?? undefined}
349	    />
350	  );
351	
352	  const handleLiveSend = async (
353	    draft: { name: string; amount: number; splitEnabled?: boolean },
354	    options: { paywave?: boolean } = {}
355	  ) => {
356	    const newTx = await createTransactionMutation.mutateAsync({
357	      itemName: draft.name,
358	      price: (draft.amount / 100).toFixed(2),
359	      selectedStoneId: selectedStoneId ?? undefined,
360	      splitEnabled: draft.splitEnabled,
361	    });
362	    // Push the new transaction into the list cache immediately so it appears in the
363	    // active stack before the next background poll fires.
364	    queryClient.setQueryData<any[]>(
365	      ["/api/merchants", merchantId, "transactions"],
366	      (prev: any[] = []) => {
367	        const exists = prev.some((t: any) => t.id === newTx.id);
368	        return exists ? prev : [newTx, ...prev];
369	      }
370	    );
371	    if (options.paywave) {
372	      startTapToPayPayment(newTx);
373	    }
374	  };
375	
376	  const handleLiveCancel = () => {
377	    if (activeTransaction?.id) {
378	      cancelTransactionMutation.mutate(activeTransaction.id);
379	    }
380	  };
381	
382	  return (
383	    <div style={{ position: "fixed", inset: 0 }}>
384	      <SmartTransitions
385	        liveState={liveState}
386	        onLiveSend={handleLiveSend}
387	        onLiveCancel={handleLiveCancel}
388	        onLivePaywave={startTapToPayPayment}
389	        onBoardSelect={(stoneId: number) => setSelectedStoneId(stoneId)}
390	        selectedStoneId={selectedStoneId}
391	        onStoneCreate={() => createStoneMutation.mutateAsync()}
392	        onStoneRename={(stoneId: number, name: string) => renameStoneMutation.mutateAsync({ stoneId, name })}
393	        onStoneDelete={(stoneId: number) => deleteStoneMutation.mutateAsync(stoneId)}
394	        liveStones={liveStones}
395	        livePayLink={livePayLink}
396	        qrElement={qrElement}
397	        showPaywave={true}
398	        successNotification={successNotif}
399	      />
400	
401	      <AnimatePresence>
402	        {showTapToPayOverlay && (
403	          <motion.div
404	            className="fixed inset-0 z-[999] flex items-center justify-center"
405	            initial={{ opacity: 0 }}
406	            animate={{ opacity: 1 }}
407	            exit={{ opacity: 0 }}
408	            style={{ backgroundColor: "#060D1F" }}
409	          >
410	            <button
411	              onClick={closeTapToPayOverlay}
412	              className="absolute top-6 right-6 w-8 h-8 rounded-full flex items-center justify-center"
413	              style={{ background: "rgba(255,255,255,0.08)" }}
414	            >
415	              <X className="h-4 w-4 text-white/60" />
416	            </button>
417	            <motion.div
418	              className="rounded-3xl p-10 max-w-sm w-full mx-6 text-center"
419	              initial={{ scale: 0.9, y: 20 }}
420	              animate={{ scale: 1, y: 0 }}
421	              style={{
422	                background: `linear-gradient(135deg, ${BRAND}14, ${BRAND}08)`,
423	                border: `1px solid ${BRAND}40`,
424	                boxShadow: `0 25px 50px rgba(0,0,0,0.6), 0 0 60px ${BRAND}18`,
425	              }}
426	            >
427	              {tapToPayStatus === "waiting" && (
428	                <div className="space-y-6">
429	                  <div
430	                    className="w-20 h-20 rounded-full flex items-center justify-center mx-auto"
431	                    style={{ border: `2px solid ${BRAND}60`, background: `${BRAND}10` }}
