441	              {tapToPayStatus === "processing" && (
442	                <div className="space-y-6">
443	                  <div
444	                    className="w-20 h-20 rounded-full flex items-center justify-center mx-auto"
445	                    style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.12)" }}
446	                  >
