469	              {tapToPayStatus === "failed" && (
470	                <div className="space-y-6">
471	                  <div
472	                    className="w-20 h-20 rounded-full flex items-center justify-center mx-auto bg-red-500/20"
473	                    style={{ border: "1px solid rgba(239,68,68,0.3)" }}
