/* ───────────────────────── Landing page (brutalist rebuild) ───────────────────────── */
/* Mirrors the terminal: flat solid color, white cards, hairline borders, micro-shadows.
   No glow, no glass, no gradients. */
.lp-root { background: #F4F4F4; color: #0A0A0A; }
.lp-root ::selection { background: #040D6D; color: #F4F4F4; }
.lp-mono { font-family: 'JetBrains Mono', ui-monospace, monospace; }

/* White card with hairline border + micro shadow (terminal idiom) */
.lp-card {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.08);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

/* Faint engineering grid — flat, no mask glow */
.lp-grid {
  background-image:
    linear-gradient(rgba(4, 13, 109, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(4, 13, 109, 0.05) 1px, transparent 1px);
  background-size: 56px 56px;
}

/* Concentric tap-to-pay rings — solid stroke, NO glow */
@keyframes lp-ring { 0% { transform: scale(.55); opacity: .7; } 100% { transform: scale(1.9); opacity: 0; } }
.lp-tap-ring { animation: lp-ring 2.4s ease-out infinite; }
.lp-tap-ring.lp-d1 { animation-delay: .8s; }
.lp-tap-ring.lp-d2 { animation-delay: 1.6s; }

@media (prefers-reduced-motion: reduce) {
  .lp-tap-ring { animation: none !important; opacity: 1 !important; }
  html.lenis, html.lenis body { scroll-behavior: auto !important; }
}

/* Lenis smooth-scroll (recommended base styles) */
html.lenis, html.lenis body { height: auto; }
.lenis.lenis-smooth { scroll-behavior: auto !important; }
.lenis.lenis-smooth [data-lenis-prevent] { overscroll-behavior: contain; }
.lenis.lenis-stopped { overflow: hidden; }
.lenis.lenis-smooth iframe { pointer-events: none; }

