import { useEffect, useRef, useState } from "react";
import { useLocation } from "wouter";
import {
  motion,
  useScroll,
  useTransform,
  useSpring,
  useInView,
  useReducedMotion,
  type MotionValue,
} from "framer-motion";
import Lenis from "lenis";
import { ArrowRight, ArrowUpRight, Nfc, Wallet, Building2, Bell, Send } from "lucide-react";
import { SEOHead } from "@/components/SEOHead";

/* ── Palette, lifted straight from the terminal (SmartTransitions.jsx) ──
   Flat, confident, brutalist. No glow, no glass, no gradients. */
const INK = "#0A0A0A";
const PAPER = "#F4F4F4";
const NAVY = "#040D6D";
const BLUE = "#58ABFF";
const GREEN = "#1BBF85";
const AMBER = "#F59E0B";

const EASE = [0.22, 1, 0.36, 1] as const;

/* ───────────────────────── Smooth scroll (Lenis) ───────────────────────── */
function useLenis(enabled: boolean) {
  const ref = useRef<Lenis | null>(null);
  useEffect(() => {
    if (!enabled) return;
    const lenis = new Lenis({
      duration: 1.1,
      easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
    });
    ref.current = lenis;
    let raf = 0;
    const loop = (time: number) => {
      lenis.raf(time);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(raf);
      lenis.destroy();
      ref.current = null;
    };
  }, [enabled]);
  return ref;
}

/* ───────────────────────── Reveal-on-scroll wrapper ───────────────────────── */
function Reveal({
  children,
  delay = 0,
  y = 26,
  className,
}: {
  children: React.ReactNode;
  delay?: number;
  y?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.35 }}
      transition={{ duration: 0.7, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}

/* ───────────────────────── Masked line reveal (hero headline) ───────────────────────── */
function Line({ children, delay = 0 }: { children: React.ReactNode; delay?: number }) {
  const reduce = useReducedMotion();
  return (
    <span className="block overflow-hidden pb-[0.08em]">
      <motion.span
        className="block"
        initial={reduce ? false : { y: "110%" }}
        animate={{ y: "0%" }}
        transition={{ duration: 0.85, ease: EASE, delay }}
      >
        {children}
      </motion.span>
    </span>
  );
}

/* ───────────────────────── Count-up (pricing) ───────────────────────── */
function CountUp({
  value,
  decimals = 2,
  prefix = "",
}: {
  value: number;
  decimals?: number;
  prefix?: string;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, margin: "-15%" });
  const reduce = useReducedMotion();
  const [n, setN] = useState(reduce ? value : 0);
  useEffect(() => {
    if (!inView || reduce) return;
    let raf = 0;
    const start = performance.now();
    const dur = 1100;
    const tick = (now: number) => {
      const p = Math.min(1, (now - start) / dur);
      setN(value * (1 - Math.pow(1 - p, 3)));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [inView, value, reduce]);
  return (
    <span ref={ref} className="tabular-nums">
      {prefix}
      {n.toFixed(decimals)}
    </span>
  );
}

/* ───────────────────────── Magnetic button (flat, no glow) ───────────────────────── */
function MagneticButton({
  children,
  onClick,
  variant = "solid",
  className = "",
}: {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: "solid" | "outline" | "light";
  className?: string;
}) {
  const reduce = useReducedMotion();
  const elRef = useRef<HTMLButtonElement>(null);
  const inner = useRef<HTMLSpanElement>(null);
  const onMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (reduce || !elRef.current || !inner.current) return;
    const r = elRef.current.getBoundingClientRect();
    inner.current.style.transform = `translate(${(e.clientX - (r.left + r.width / 2)) * 0.25}px, ${
      (e.clientY - (r.top + r.height / 2)) * 0.3
    }px)`;
  };
  const onLeave = () => {
    if (inner.current) inner.current.style.transform = "translate(0,0)";
  };
  const styles: Record<string, React.CSSProperties> = {
    solid: { background: NAVY, color: PAPER },
    light: { background: INK, color: PAPER },
    outline: { background: "transparent", color: INK, border: `1.5px solid ${INK}` },
  };
  return (
    <button
      ref={elRef}
      onClick={onClick}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      style={styles[variant]}
      className={`group inline-flex items-center justify-center gap-2 rounded-full px-7 py-3.5 text-sm font-semibold lowercase tracking-wide transition-[background,color] duration-200 ${className}`}
    >
      <span ref={inner} className="inline-flex items-center gap-2 transition-transform duration-300 ease-out [pointer-events:none]">
        {children}
      </span>
    </button>
  );
}

/* ───────────────────────── Tap-to-pay visual (payments pillar / hero) ───────────────────────── */
function TapToPayCard({ accent = NAVY }: { accent?: string }) {
  return (
    <div className="lp-card w-full max-w-sm rounded-[28px] p-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="grid h-7 w-7 place-items-center rounded-lg" style={{ background: accent }}>
            <span className="text-[13px] font-bold" style={{ color: PAPER }}>t</span>
          </span>
          <span className="lp-mono text-xs tracking-wide text-black/55">tapt terminal</span>
        </div>
        <span className="lp-mono text-[10px] uppercase tracking-[0.2em]" style={{ color: GREEN }}>
          ● live
        </span>
      </div>

      <div className="mt-7 text-center">
        <p className="lp-mono text-[11px] uppercase tracking-[0.3em] text-black/40">amount due</p>
        <p className="mt-1.5 text-5xl font-semibold tracking-tight tabular-nums text-[#0A0A0A]">
          $48<span className="text-black/30">.00</span>
        </p>
        <p className="mt-1.5 text-sm text-black/45">the corner roastery · #2048</p>
      </div>

      <div className="relative mx-auto mt-7 grid h-28 w-28 place-items-center">
        <span className="lp-tap-ring absolute h-20 w-20 rounded-full border-2" style={{ borderColor: `${accent}99` }} />
        <span className="lp-tap-ring lp-d1 absolute h-20 w-20 rounded-full border-2" style={{ borderColor: `${accent}66` }} />
        <span className="lp-tap-ring lp-d2 absolute h-20 w-20 rounded-full border-2" style={{ borderColor: `${accent}33` }} />
        <span className="grid h-16 w-16 place-items-center rounded-full" style={{ background: accent }}>
          <Nfc className="h-7 w-7" style={{ color: PAPER }} strokeWidth={2} />
        </span>
      </div>
      <p className="lp-mono mt-4 text-center text-xs uppercase tracking-[0.25em] text-black/40">tap to pay</p>

      <div className="mt-6 flex items-center justify-center gap-2">
        {["apple pay", "google pay", "card"].map((w) => (
          <span
            key={w}
            className="lp-mono rounded-full border border-black/10 px-3 py-1 text-[10px] uppercase tracking-wider text-black/50"
          >
            {w}
          </span>
        ))}
      </div>
    </div>
  );
}

/* ───────────────────────── Rent visual (property pillar) ───────────────────────── */
function RentCard() {
  const rows = [
    { unit: "12B · m. chen", amount: "$540", status: "paid", color: GREEN },
    { unit: "4A · the okafors", amount: "$610", status: "paid", color: GREEN },
    { unit: "9C · s. patel", amount: "$575", status: "awaiting", color: AMBER },
  ];
  return (
    <div className="lp-card w-full max-w-sm rounded-[28px] p-6">
      <div className="flex items-center justify-between">
        <div>
          <p className="lp-mono text-[11px] uppercase tracking-[0.25em] text-black/40">march rent</p>
          <p className="mt-1 text-2xl font-semibold tracking-tight text-[#0A0A0A]">$1,725 collected</p>
        </div>
        <span className="grid h-9 w-9 place-items-center rounded-lg" style={{ background: NAVY }}>
          <Building2 className="h-4 w-4" style={{ color: PAPER }} />
        </span>
      </div>

      <div className="mt-5 space-y-2.5">
        {rows.map((r) => (
          <div
            key={r.unit}
            className="flex items-center justify-between rounded-2xl border border-black/[0.06] bg-[#F8F9FF] px-4 py-3"
          >
            <span className="text-sm font-medium text-[#0A0A0A]">{r.unit}</span>
            <span className="flex items-center gap-2">
              <span className="text-sm tabular-nums text-black/60">{r.amount}</span>
              <span className="h-1.5 w-1.5 rounded-full" style={{ background: r.color }} />
              <span className="lp-mono text-[10px] uppercase tracking-wider text-black/45">{r.status}</span>
            </span>
          </div>
        ))}
      </div>

      <button
        type="button"
        className="lp-mono mt-5 flex w-full items-center justify-center gap-2 rounded-full py-3 text-[11px] uppercase tracking-[0.2em]"
        style={{ background: NAVY, color: PAPER }}
      >
        <Bell className="h-3.5 w-3.5" /> send reminders
      </button>
    </div>
  );
}

/* ───────────────────────── Pinned two-pillar section ───────────────────────── */
function Pillars() {
  const ref = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end end"] });

  // Crossfade: panel A (payments) 0→0.5, panel B (property) 0.5→1
  const aOpacity = useTransform(scrollYProgress, [0, 0.4, 0.52], [1, 1, 0]);
  const aY = useTransform(scrollYProgress, [0, 0.52], [0, -40]);
  const bOpacity = useTransform(scrollYProgress, [0.48, 0.6, 1], [0, 1, 1]);
  const bY = useTransform(scrollYProgress, [0.48, 1], [40, 0]);
  const indexProgress = useTransform(scrollYProgress, [0.45, 0.55], [0, 1]);

  return (
    <section id="pillars" ref={ref} className="relative" style={{ height: "260vh" }}>
      <div className="sticky top-0 flex h-screen items-center justify-center overflow-hidden">
        {/* Panel A — payments (navy) */}
        <Panel
          opacity={aOpacity}
          y={aY}
          bg={NAVY}
          fg={PAPER}
          index="01"
          label="payments"
          accent={BLUE}
          title={
            <>
              collect payments,
              <br />
              <span style={{ color: BLUE }}>effortlessly.</span>
            </>
          }
          body="Tap to pay on the phone you already own. Apple Pay, Google Pay, contactless — instant settlement, no terminal, no hardware, no waiting."
          chips={["digital wallet", "contactless", "instant settlement"]}
          icon={<Wallet className="h-4 w-4" />}
          visual={<TapToPayCard accent={NAVY} />}
        />

        {/* Panel B — property (sky-blue) */}
        <Panel
          opacity={bOpacity}
          y={bY}
          bg={BLUE}
          fg={NAVY}
          index="02"
          label="property"
          accent={NAVY}
          title={
            <>
              collect rent,
              <br />
              on autopilot.
            </>
          }
          body="Send rent requests, automate reminders, and see who's paid at a glance. Built for property managers who want rent collected — without the chasing."
          chips={["rent requests", "auto reminders", "paid tracking"]}
          icon={<Building2 className="h-4 w-4" />}
          visual={<RentCard />}
        />

        {/* Progress index */}
        <div className="pointer-events-none absolute bottom-8 left-1/2 z-10 flex -translate-x-1/2 items-center gap-3">
          <Dot active={indexProgress} flip={false} />
          <Dot active={indexProgress} flip={true} />
        </div>
      </div>
    </section>
  );
}

function Dot({ active, flip }: { active: MotionValue<number>; flip: boolean }) {
  const w = useTransform(active, [0, 1], flip ? [10, 36] : [36, 10]);
  const o = useTransform(active, [0, 1], flip ? [0.3, 1] : [1, 0.3]);
  return <motion.span className="h-1.5 rounded-full bg-current" style={{ width: w, opacity: o }} />;
}

function Panel({
  opacity,
  y,
  bg,
  fg,
  index,
  label,
  accent,
  title,
  body,
  chips,
  icon,
  visual,
}: {
  opacity: MotionValue<number>;
  y: MotionValue<number>;
  bg: string;
  fg: string;
  index: string;
  label: string;
  accent: string;
  title: React.ReactNode;
  body: string;
  chips: string[];
  icon: React.ReactNode;
  visual: React.ReactNode;
}) {
  return (
    <motion.div
      style={{ opacity, backgroundColor: bg, color: fg }}
      className="absolute inset-0 flex items-center"
    >
      <div className="mx-auto grid w-full max-w-7xl items-center gap-12 px-6 lg:grid-cols-2 lg:px-10">
        <motion.div style={{ y }}>
          <div className="lp-mono flex items-center gap-3 text-[11px] uppercase tracking-[0.25em]" style={{ opacity: 0.75 }}>
            <span className="grid h-7 w-7 place-items-center rounded-lg" style={{ background: accent, color: bg }}>
              {icon}
            </span>
            {index} — {label}
          </div>
          <h2 className="mt-6 text-5xl font-semibold leading-[0.98] tracking-tight sm:text-6xl lg:text-7xl">
            {title}
          </h2>
          <p className="mt-6 max-w-md text-lg leading-relaxed" style={{ opacity: 0.8 }}>
            {body}
          </p>
          <div className="mt-7 flex flex-wrap gap-2">
            {chips.map((c) => (
              <span
                key={c}
                className="lp-mono rounded-full px-3 py-1.5 text-[10px] uppercase tracking-wider"
                style={{ border: `1px solid ${fg}33`, color: fg }}
              >
                {c}
              </span>
            ))}
          </div>
        </motion.div>

        <motion.div style={{ y }} className="flex justify-center lg:justify-end">
          {visual}
        </motion.div>
      </div>
    </motion.div>
  );
}

/* ───────────────────────── Page ───────────────────────── */
export function LandingPage() {
  const [, setLocation] = useLocation();
  const reduce = useReducedMotion();
  const goLogin = () => setLocation("/login");

  const lenis = useLenis(!reduce);
  const scrollTo = (target: string) => {
    if (lenis.current) lenis.current.scrollTo(target, { offset: -20 });
    else document.querySelector(target)?.scrollIntoView({ behavior: "smooth" });
  };

  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", fn, { passive: true });
    return () => window.removeEventListener("scroll", fn);
  }, []);

  // Top progress bar
  const { scrollYProgress } = useScroll();
  const barX = useSpring(scrollYProgress, { stiffness: 120, damping: 30, mass: 0.3 });

  return (
    <div className="lp-root min-h-screen overflow-x-hidden" style={{ fontFamily: "Outfit, sans-serif" }}>
      <SEOHead
        title="TaptPay – Low Cost EFTPOS & POS System NZ | Digital Point of Sale"
        description="New Zealand's lowest-cost EFTPOS alternative and digital POS system. No hardware, no lock-in contracts. Accept QR code and NFC contactless payments instantly. 100% Kiwi owned."
        keywords="EFTPOS NZ, POS system NZ, digital POS, POS solutions, low cost POS system, point of sale New Zealand, cheap EFTPOS machine, cloud POS NZ, small business POS NZ, contactless payments NZ, mobile POS NZ, QR code payments, NFC payments, EFTPOS alternative, payment terminal NZ, rent collection NZ, property management payments"
        ogTitle="TaptPay – NZ's Lowest-Cost EFTPOS & POS System | No Hardware Required"
        ogDescription="Ditch the EFTPOS machine. TaptPay is New Zealand's 100% digital POS system — accept contactless payments and collect rent with no hardware and no lock-in contracts."
        canonicalUrl="https://taptpay.com/"
      />

      {/* Scroll progress bar */}
      <motion.div
        className="fixed inset-x-0 top-0 z-[60] h-[3px] origin-left"
        style={{ scaleX: barX, background: NAVY }}
      />

      {/* ───── NAV ───── */}
      <header className="fixed inset-x-0 top-0 z-50 transition-colors duration-300">
        <nav
          className="mx-auto flex max-w-7xl items-center justify-between px-6 py-4 lg:px-10"
          style={{
            background: scrolled ? "rgba(244,244,244,0.85)" : "transparent",
            backdropFilter: scrolled ? "saturate(140%) blur(6px)" : "none",
            borderBottom: scrolled ? "1px solid rgba(0,0,0,0.07)" : "1px solid transparent",
