              <span className="text-base font-bold" style={{ color: PAPER }}>t</span>
            </span>
            <span className="text-lg font-semibold tracking-tight text-[#0A0A0A]">tapt</span>
          </button>

          <div className="hidden items-center gap-8 text-sm text-black/55 md:flex">
            <button onClick={() => scrollTo("#pillars")} className="lowercase transition-colors hover:text-[#0A0A0A]">payments</button>
            <button onClick={() => scrollTo("#pillars")} className="lowercase transition-colors hover:text-[#0A0A0A]">property</button>
            <button onClick={() => scrollTo("#pricing")} className="lowercase transition-colors hover:text-[#0A0A0A]">pricing</button>
          </div>

          <MagneticButton onClick={goLogin} variant="solid" className="!px-5 !py-2.5" >
            get started
          </MagneticButton>
        </nav>
      </header>

      <main id="top">
        {/* ───── HERO ───── */}
        <section className="relative mx-auto max-w-7xl px-6 pb-24 pt-36 sm:pt-44 lg:px-10 lg:pt-52">
          <div className="lp-grid pointer-events-none absolute inset-x-0 top-0 -z-10 h-[60vh]" />

          <motion.div
            initial={reduce ? false : { opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, ease: EASE }}
            className="lp-mono flex items-center gap-2 text-[11px] uppercase tracking-[0.25em] text-black/45"
          >
            <span className="h-1.5 w-1.5 rounded-full" style={{ background: GREEN }} />
            the end of the eftpos terminal
          </motion.div>

          <h1 className="mt-6 text-6xl font-semibold leading-[0.92] tracking-tight text-[#0A0A0A] sm:text-7xl lg:text-[7rem]">
            <Line delay={0.05}>goodbye,</Line>
            <Line delay={0.13}>terminal.</Line>
            <span className="mt-3 block overflow-hidden">
              <motion.span
                className="mt-1 inline-block px-4 py-1"
                style={{ background: NAVY, color: PAPER }}
                initial={reduce ? false : { y: "110%" }}
                animate={{ y: "0%" }}
                transition={{ duration: 0.85, ease: EASE, delay: 0.24 }}
              >
                hello, <span style={{ color: BLUE }}>everywhere.</span>
              </motion.span>
            </span>
          </h1>

          <motion.p
            initial={reduce ? false : { opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, ease: EASE, delay: 0.4 }}
            className="mt-8 max-w-xl text-lg leading-relaxed text-black/60 sm:text-xl"
          >
            Take instant payments and collect rent from the device you already own.
