            <h2 className="mt-4 max-w-2xl text-4xl font-semibold tracking-tight text-[#0A0A0A] sm:text-5xl">
              three steps to paid.
            </h2>
          </Reveal>

          <div className="mt-14 grid gap-px overflow-hidden rounded-3xl border border-black/[0.08] bg-black/[0.08] md:grid-cols-3">
            {[
              { n: "01", icon: <Send className="h-5 w-5" />, t: "create a request", b: "Enter an amount — a sale or a tenant's rent. Send it, or show the tap zone." },
              { n: "02", icon: <Nfc className="h-5 w-5" />, t: "they tap to pay", b: "Customer or tenant pays with Apple Pay, Google Pay, card, or QR. One tap." },
              { n: "03", icon: <Wallet className="h-5 w-5" />, t: "settled instantly", b: "Money lands, status flips to paid, everyone gets a receipt. No chasing." },
            ].map((s, i) => (
              <Reveal key={s.n} delay={i * 0.08}>
                <div className="flex h-full flex-col bg-[#F4F4F4] p-8">
                  <div className="flex items-center justify-between">
                    <span className="grid h-11 w-11 place-items-center rounded-xl" style={{ background: NAVY, color: PAPER }}>
                      {s.icon}
                    </span>
                    <span className="lp-mono text-3xl font-semibold text-black/15">{s.n}</span>
                  </div>
                  <h3 className="mt-8 text-xl font-semibold text-[#0A0A0A]">{s.t}</h3>
                  <p className="mt-2 leading-relaxed text-black/55">{s.b}</p>
                </div>
              </Reveal>
            ))}
          </div>
        </section>

        {/* ───── PRICING ───── */}
        <section id="pricing" className="mx-auto max-w-7xl px-6 py-28 lg:px-10">
          <div className="grid gap-12 lg:grid-cols-[1fr_1.1fr] lg:gap-20">
            <Reveal>
              <p className="lp-mono text-[11px] uppercase tracking-[0.3em]" style={{ color: NAVY }}>pricing</p>
              <h2 className="mt-4 text-4xl font-semibold tracking-tight text-[#0A0A0A] sm:text-5xl">
                honest, flat pricing.
              </h2>
              <p className="mt-6 max-w-sm text-lg leading-relaxed text-black/55">
                No contracts. No rental traps. Pay per transaction, and a small software fee only if you go big.
              </p>
              <div className="mt-10 flex items-end gap-6">
                <div>
                  <p className="text-6xl font-semibold tracking-tight text-[#0A0A0A]">
                    <CountUp value={0.1} decimals={2} prefix="$" />
                  </p>
                  <p className="lp-mono mt-2 text-[11px] uppercase tracking-wider text-black/40">per transaction</p>
                </div>
                <div className="pb-2">
                  <p className="text-3xl font-semibold tracking-tight" style={{ color: NAVY }}>
                    <CountUp value={9.99} decimals={2} prefix="$" />
                  </p>
                  <p className="lp-mono mt-1 text-[11px] uppercase tracking-wider text-black/40">/mo over 100 txns</p>
                </div>
              </div>
              <div className="mt-10">
                <MagneticButton onClick={goLogin} variant="light">
                  get started for free <ArrowRight className="h-4 w-4" />
                </MagneticButton>
              </div>
            </Reveal>

            <Reveal delay={0.1}>
              <div className="lp-card overflow-hidden rounded-3xl">
                {[
                  { k: "Per transaction", v: "$0.10" },
                  { k: "Monthly software fee", v: "$9.99 (only over 100 txns)" },
                  { k: "Contract", v: "None" },
                  { k: "Technical support", v: "Free" },
                  { k: "Payment board (A5)", v: "$25.99 · first 2 designs free" },
                  { k: "Custom board size", v: "On request" },
                ].map((row, i) => (
                  <div
                    key={row.k}
                    className="flex items-center justify-between px-7 py-5"
                    style={{ borderTop: i === 0 ? "none" : "1px solid rgba(0,0,0,0.07)" }}
                  >
                    <span className="text-black/55">{row.k}</span>
                    <span className="text-right font-medium text-[#0A0A0A]">{row.v}</span>
                  </div>
                ))}
              </div>
            </Reveal>
          </div>
        </section>

        {/* ───── FINAL CTA ───── */}
        <section className="mx-auto max-w-7xl px-6 pb-28 lg:px-10">
          <Reveal>
            <div className="relative overflow-hidden rounded-[2.5rem] px-8 py-20 text-center sm:px-16 sm:py-28" style={{ background: NAVY }}>
              <div className="lp-grid pointer-events-none absolute inset-0 opacity-[0.15]" />
              <div className="relative">
                <h2 className="mx-auto max-w-3xl text-4xl font-semibold leading-[1.02] tracking-tight sm:text-6xl" style={{ color: PAPER }}>
                  start collecting <span style={{ color: BLUE }}>today.</span>
                </h2>
                <p className="mx-auto mt-5 max-w-md text-lg" style={{ color: "rgba(244,244,244,0.7)" }}>
                  No sales call. No hardware order. Just you, your device, and your first payment.
                </p>
                <div className="mt-9 flex justify-center">
                  <MagneticButton
                    onClick={goLogin}
                    className="!bg-[#58ABFF] !text-[#040D6D]"
                  >
                    get started <ArrowUpRight className="h-4 w-4" />
                  </MagneticButton>
                </div>
                <p className="lp-mono mt-6 text-[11px] uppercase tracking-[0.2em]" style={{ color: "rgba(244,244,244,0.5)" }}>
                  live in minutes · cancel anytime
                </p>
              </div>
            </div>
          </Reveal>
        </section>
      </main>

      {/* ───── FOOTER ───── */}
      <footer className="border-t border-black/[0.08]">
        <div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-6 px-6 py-10 sm:flex-row lg:px-10">
          <button onClick={() => scrollTo("#top")} className="flex items-center gap-2.5">
            <span className="grid h-7 w-7 place-items-center rounded-lg" style={{ background: NAVY }}>
              <span className="text-sm font-bold" style={{ color: PAPER }}>t</span>
            </span>
            <span className="font-semibold tracking-tight text-[#0A0A0A]">tapt</span>
          </button>

          <div className="flex items-center gap-8 text-sm text-black/50">
            <a href="/privacy" className="lowercase transition-colors hover:text-[#0A0A0A]">privacy</a>
            <a href="/terms" className="lowercase transition-colors hover:text-[#0A0A0A]">terms</a>
            <button onClick={() => scrollTo("#pricing")} className="lowercase transition-colors hover:text-[#0A0A0A]">pricing</button>
          </div>

          <p className="lp-mono text-xs text-black/40">© 2026 tapt — payments, freed.</p>
        </div>
      </footer>
    </div>
  );
}

