import { chromium } from 'playwright';
const errors = [];
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://localhost:5000/', { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1500);
const heroOk = await page.getByText('goodbye,').first().isVisible().catch(()=>false);
const payOk  = await page.getByText('collect payments,').first().count();
const rentOk = await page.getByText('collect rent,').first().count();
// scroll through pinned pillars + pricing to trigger scroll animations / count-ups
for (let y = 0; y <= 6000; y += 600) { await page.mouse.wheel(0, 600); await page.waitForTimeout(120); }
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/landing-hero.png' });
await page.evaluate(() => window.scrollTo(0,0));
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/landing-top.png' });
console.log('hero visible:', heroOk);
console.log('payments pillar present:', payOk);
console.log('rent pillar present:', rentOk);
console.log('console errors:', errors.length);
errors.slice(0,10).forEach(e => console.log('  -', e));
await browser.close();
EOF
PLAYWRIGHT_BROWSERS_PATH=/tmp/pw node /tmp/smoke.mjs 2>&1

